import{_ as a,o,c as s,a2 as i}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Introducción a PHP y entorno","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/backend/php/01-introduccion-a-php-y-entorno.md","filePath":"full-stack/backend/php/01-introduccion-a-php-y-entorno.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"full-stack/backend/php/01-introduccion-a-php-y-entorno.md"};function t(r,e,l,p,d,c){return o(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="introduccion-a-php-y-entorno" tabindex="-1">Introducción a PHP y entorno <a class="header-anchor" href="#introduccion-a-php-y-entorno" aria-label="Permalink to &quot;Introducción a PHP y entorno&quot;">​</a></h1><p>PHP es un lenguaje pensado para ejecutarse <strong>en el servidor</strong>: el intérprete genera HTML, JSON o texto y el cliente solo ve el resultado. No corre en el navegador (salvo que lo uses como CLI en tu máquina).</p><p>Documentación oficial: <a href="https://www.php.net/manual/es/" target="_blank" rel="noreferrer">manual PHP</a>, <a href="https://www.php.net/manual/es/features.commandline.webserver.php" target="_blank" rel="noreferrer">servidor web integrado</a>, <a href="https://www.php.net/manual/es/features.commandline.php" target="_blank" rel="noreferrer">uso de la CLI</a>.</p><h2 id="cli-frente-a-servidor-web" tabindex="-1">CLI frente a servidor web <a class="header-anchor" href="#cli-frente-a-servidor-web" aria-label="Permalink to &quot;CLI frente a servidor web&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modo</th><th>Qué hace</th><th>Para qué</th></tr></thead><tbody><tr><td><strong>CLI</strong> (<code>php script.php</code>)</td><td>Ejecuta un fichero y escribe en stdout.</td><td>Scripts, cron, comprobar la instalación.</td></tr><tr><td><strong>Módulo / php-fpm + Apache/Nginx</strong></td><td>PHP responde peticiones HTTP reales.</td><td>Producción.</td></tr><tr><td><strong>Servidor integrado</strong> (<code>php -S</code>)</td><td>Un proceso de desarrollo que sirve el directorio actual.</td><td>Probar formularios en local. <strong>No es un servidor de producción.</strong></td></tr></tbody></table><p>El manual oficial lo deja claro: el built-in server es para desarrollo y demos controladas; es un solo proceso (en versiones recientes puede forkar workers, pero sigue sin ser un servidor de internet). En público usas php-fpm (o equivalente) detrás de Nginx/Apache.</p><h2 id="comprobar-la-instalacion" tabindex="-1">Comprobar la instalación <a class="header-anchor" href="#comprobar-la-instalacion" aria-label="Permalink to &quot;Comprobar la instalación&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>Debes ver una línea <code>PHP 8.x...</code>. Si el comando no existe, instala el paquete de tu distro o el binario de <a href="https://www.php.net/downloads.php" target="_blank" rel="noreferrer">php.net/downloads</a>. Este manual asume <strong>PHP 8</strong>.</p><p>Ejecutar un script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hola.php</span></span></code></pre></div><h2 id="fichero-minimo" tabindex="-1">Fichero mínimo <a class="header-anchor" href="#fichero-minimo" aria-label="Permalink to &quot;Fichero mínimo&quot;">​</a></h2><p>Un fichero PHP empieza por la etiqueta de apertura. Lo que va <strong>fuera</strong> de <code>&lt;?php ... ?&gt;</code> se envía tal cual (HTML). En CLI suele bastar un fichero solo con PHP:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">php</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Iago&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hola, </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$name</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Guárdalo como <code>hola.php</code> y lánzalo con <code>php hola.php</code>. <code>echo</code> escribe a la salida; <code>&quot;Hola, $name\\n&quot;</code> interpola la variable (el capítulo 2 cubre tipos y comillas).</p><p>Servidor de desarrollo (desde el directorio del proyecto):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:8080</span></span></code></pre></div><p>Abre <code>http://127.0.0.1:8080/hola.php</code>. Eso <strong>no</strong> sustituye a Nginx ni a un hosting. No lo expongas a una red pública.</p><h2 id="cuando-encaja-php" tabindex="-1">Cuándo encaja PHP <a class="header-anchor" href="#cuando-encaja-php" aria-label="Permalink to &quot;Cuándo encaja PHP&quot;">​</a></h2><ul><li>Páginas o APIs donde el servidor arma la respuesta.</li><li>Código existente (CMS, paneles, scripts de mantenimiento).</li><li>Un lenguaje con un runtime único: no hay un “bundle” de frontend.</li></ul><p>No es el único camino: Node, Python o Go cubren el mismo hueco. PHP brilla cuando quieres HTML generado en servidor con poco andamiaje. Los frameworks (Laravel, Symfony) <strong>abstraen</strong> enrutado, plantillas y ORM; este manual enseña el lenguaje, no un framework.</p><p>El resto del recorrido: tipos → control y funciones → arrays → HTTP/formularios → sesiones → ficheros → PDO → OOP.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Tratar <code>php -S</code> como despliegue.</li><li>Subir un <code>.php</code> y esperar que el navegador lo interprete sin un SAPI (Apache/php-fpm/Caddy, etc.).</li><li>Mezclar HTML y lógica sin un plan: más adelante (capítulos 11–12) se separa; aquí basta con scripts claros.</li><li>Copiar recetas de PHP 5 (<code>mysql_query</code>, <code>each()</code>, <code>create_function</code>).</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Comprueba <code>php -v</code> en cada máquina (local, CI, servidor).</li><li>Un fichero = un propósito al empezar.</li><li>En web, el DocumentRoot no debe ser “todo el disco”: solo lo público.</li><li>Producción: PHP-FPM + proxy, no el servidor integrado.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Crea <code>hola.php</code> con el snippet de arriba y ejecútalo en CLI.</li><li>Cambia <code>$name</code> y vuelve a lanzarlo.</li><li>Arranca <code>php -S localhost:8080</code> y ábrelo en el navegador. Luego <strong>apágalo</strong>. No lo dejes escuchando en <code>0.0.0.0</code> en una red compartida.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./02-sintaxis-basica-y-tipos-de-datos">Sintaxis básica y tipos de datos</a>.</p>`,30)])])}const b=a(n,[["render",t]]);export{u as __pageData,b as default};
